-- Supabase PostgreSQL migration. Run as postgres / service owner.
BEGIN;
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS divisions (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS job_titles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS hsk_levels (id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 6), curriculum TEXT NOT NULL DEFAULT 'HSK3.0');
CREATE TABLE IF NOT EXISTS profiles (
 id UUID PRIMARY KEY, employee_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
 email TEXT NOT NULL, department TEXT NOT NULL REFERENCES departments(id), division TEXT NOT NULL, job_title TEXT NOT NULL,
 role TEXT NOT NULL DEFAULT 'employee' CHECK(role IN ('employee','leader')),
 password_hash TEXT, self_level INTEGER NOT NULL CHECK(self_level BETWEEN 1 AND 6), placement_level INTEGER,
 baseline_hsk DOUBLE PRECISION, baseline_work DOUBLE PRECISION, hsk_benchmark TEXT, work_benchmark TEXT,
 demo INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES profiles(id), csrf TEXT NOT NULL, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reset_tokens (id TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES profiles(id), expires_at BIGINT NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY, window_start BIGINT NOT NULL, attempts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_config (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_versions (id UUID PRIMARY KEY, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','under_review','approved','published','archived')), reviewer TEXT, demo INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS learning_packages (id UUID PRIMARY KEY, title TEXT NOT NULL, track TEXT NOT NULL CHECK(track IN ('hsk','work')), level INTEGER, ordinal INTEGER NOT NULL, demo INTEGER NOT NULL DEFAULT 0, UNIQUE(track,level,ordinal));
CREATE TABLE IF NOT EXISTS vocabulary (id UUID PRIMARY KEY, hanzi TEXT NOT NULL, pinyin TEXT NOT NULL, meaning TEXT NOT NULL, track TEXT NOT NULL CHECK(track IN ('hsk','work')), level INTEGER, department TEXT, version_id UUID NOT NULL REFERENCES content_versions(id));
CREATE TABLE IF NOT EXISTS package_vocabulary (package_id UUID NOT NULL REFERENCES learning_packages(id), vocabulary_id UUID NOT NULL REFERENCES vocabulary(id), PRIMARY KEY(package_id,vocabulary_id));
CREATE TABLE IF NOT EXISTS questions (id UUID PRIMARY KEY, track TEXT NOT NULL CHECK(track IN ('hsk','work')), level INTEGER, department TEXT, kind TEXT NOT NULL, direction TEXT, prompt TEXT NOT NULL, options TEXT NOT NULL, correct_id TEXT NOT NULL, explanation TEXT NOT NULL, weight DOUBLE PRECISION NOT NULL DEFAULT 1 CHECK(weight > 0), benchmark TEXT, version_id UUID NOT NULL REFERENCES content_versions(id));
CREATE TABLE IF NOT EXISTS question_options (id UUID PRIMARY KEY, question_id UUID NOT NULL REFERENCES questions(id), label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exam_sessions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES profiles(id), track TEXT NOT NULL, mode TEXT NOT NULL, level INTEGER NOT NULL, week TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','submitted','void')), started_at BIGINT NOT NULL, deadline BIGINT NOT NULL, submitted_at BIGINT, official INTEGER NOT NULL DEFAULT 0, demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS exam_session_questions (session_id UUID NOT NULL REFERENCES exam_sessions(id), question_id UUID NOT NULL, ordinal INTEGER NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY(session_id,question_id), UNIQUE(session_id,ordinal));
CREATE TABLE IF NOT EXISTS exam_answers (session_id UUID NOT NULL REFERENCES exam_sessions(id), question_id UUID NOT NULL, option_id TEXT NOT NULL, saved_at BIGINT NOT NULL, PRIMARY KEY(session_id,question_id), FOREIGN KEY(session_id,question_id) REFERENCES exam_session_questions(session_id,question_id));
CREATE TABLE IF NOT EXISTS exam_results (id UUID PRIMARY KEY, session_id UUID NOT NULL UNIQUE REFERENCES exam_sessions(id), user_id UUID NOT NULL REFERENCES profiles(id), score DOUBLE PRECISION NOT NULL CHECK(score BETWEEN 0 AND 100), passed INTEGER NOT NULL, official_key TEXT UNIQUE, benchmark TEXT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS placement_sessions (id UUID PRIMARY KEY REFERENCES exam_sessions(id), level INTEGER NOT NULL, score DOUBLE PRECISION, benchmark TEXT);
CREATE TABLE IF NOT EXISTS placement_answers (session_id UUID NOT NULL REFERENCES placement_sessions(id), question_id UUID NOT NULL, option_id TEXT NOT NULL, PRIMARY KEY(session_id,question_id));
CREATE TABLE IF NOT EXISTS weekly_targets (user_id UUID NOT NULL REFERENCES profiles(id), week TEXT NOT NULL, target_minutes INTEGER NOT NULL DEFAULT 60, PRIMARY KEY(user_id,week));
CREATE TABLE IF NOT EXISTS learning_sessions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES profiles(id), package_id UUID NOT NULL REFERENCES learning_packages(id), started_at BIGINT NOT NULL, last_heartbeat BIGINT NOT NULL, active_seconds INTEGER NOT NULL DEFAULT 0, closed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS learning_progress (user_id UUID NOT NULL REFERENCES profiles(id), package_id UUID NOT NULL REFERENCES learning_packages(id), completed INTEGER NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,package_id));
CREATE TABLE IF NOT EXISTS notification_preferences (user_id UUID PRIMARY KEY REFERENCES profiles(id), in_app INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES profiles(id), dedupe TEXT NOT NULL UNIQUE, message TEXT NOT NULL, read_at BIGINT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ranking_policy_versions (id TEXT PRIMARY KEY, formula TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ranking_snapshots (id UUID PRIMARY KEY, period TEXT NOT NULL, period_start BIGINT NOT NULL, policy_id TEXT NOT NULL REFERENCES ranking_policy_versions(id), data TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(period,period_start,policy_id));
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY, user_id UUID REFERENCES profiles(id), action TEXT NOT NULL, detail TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_exam_user ON exam_sessions(user_id,started_at);
CREATE INDEX IF NOT EXISTS idx_exam_week ON exam_sessions(week,mode,track);
CREATE INDEX IF NOT EXISTS idx_question_pool ON questions(track,level,department,kind);
CREATE INDEX IF NOT EXISTS idx_learning_user ON learning_sessions(user_id,started_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_profile_email ON profiles(LOWER(email));
CREATE UNIQUE INDEX IF NOT EXISTS idx_single_leader ON profiles(role) WHERE role='leader';
CREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_exam ON exam_sessions(user_id) WHERE status='active';

CREATE TABLE IF NOT EXISTS question_metadata (question_id UUID PRIMARY KEY REFERENCES questions(id), concept_key TEXT NOT NULL, source_ref TEXT NOT NULL, curriculum TEXT NOT NULL, difficulty INTEGER, transformation TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_question_concept ON question_metadata(concept_key);
CREATE TABLE IF NOT EXISTS vocabulary_metadata (vocabulary_id UUID PRIMARY KEY REFERENCES vocabulary(id), source_ref TEXT NOT NULL, part_of_speech TEXT, examples TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS learning_lessons (id UUID PRIMARY KEY, title TEXT NOT NULL, track TEXT NOT NULL, level INTEGER, department TEXT, kind TEXT NOT NULL, body TEXT NOT NULL, source_ref TEXT NOT NULL, version_id UUID NOT NULL REFERENCES content_versions(id));
CREATE TABLE IF NOT EXISTS package_lessons (package_id UUID NOT NULL REFERENCES learning_packages(id), lesson_id UUID NOT NULL REFERENCES learning_lessons(id), PRIMARY KEY(package_id,lesson_id));
CREATE TABLE IF NOT EXISTS source_assets (id UUID PRIMARY KEY, title TEXT NOT NULL, path TEXT NOT NULL UNIQUE, media_type TEXT NOT NULL, track TEXT NOT NULL, level INTEGER, legacy INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, sha256 TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exam_session_metadata (session_id UUID PRIMARY KEY REFERENCES exam_sessions(id), curriculum TEXT NOT NULL, content_mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_curriculum (user_id UUID PRIMARY KEY REFERENCES profiles(id), curriculum TEXT NOT NULL, migrated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS exam_exposure_order (session_id UUID PRIMARY KEY REFERENCES exam_sessions(id), ordinal BIGINT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS learning_session_metadata (session_id UUID PRIMARY KEY REFERENCES learning_sessions(id), content_mode TEXT NOT NULL);

-- No browser mutation grants. All writes go through the authenticated, authorized server.
ALTER TABLE departments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON departments FROM anon, authenticated;
ALTER TABLE divisions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON divisions FROM anon, authenticated;
ALTER TABLE job_titles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON job_titles FROM anon, authenticated;
ALTER TABLE hsk_levels ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hsk_levels FROM anon, authenticated;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON profiles FROM anon, authenticated;
ALTER TABLE auth_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON auth_sessions FROM anon, authenticated;
ALTER TABLE reset_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON reset_tokens FROM anon, authenticated;
ALTER TABLE rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON rate_limits FROM anon, authenticated;
ALTER TABLE app_config ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_config FROM anon, authenticated;
ALTER TABLE content_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON content_versions FROM anon, authenticated;
ALTER TABLE learning_packages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON learning_packages FROM anon, authenticated;
ALTER TABLE vocabulary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON vocabulary FROM anon, authenticated;
ALTER TABLE package_vocabulary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON package_vocabulary FROM anon, authenticated;
ALTER TABLE questions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON questions FROM anon, authenticated;
ALTER TABLE question_options ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON question_options FROM anon, authenticated;
ALTER TABLE exam_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_sessions FROM anon, authenticated;
ALTER TABLE exam_session_questions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_session_questions FROM anon, authenticated;
ALTER TABLE exam_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_answers FROM anon, authenticated;
ALTER TABLE exam_results ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_results FROM anon, authenticated;
ALTER TABLE placement_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON placement_sessions FROM anon, authenticated;
ALTER TABLE placement_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON placement_answers FROM anon, authenticated;
ALTER TABLE weekly_targets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON weekly_targets FROM anon, authenticated;
ALTER TABLE learning_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON learning_sessions FROM anon, authenticated;
ALTER TABLE learning_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON learning_progress FROM anon, authenticated;
ALTER TABLE notification_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON notification_preferences FROM anon, authenticated;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON notifications FROM anon, authenticated;
ALTER TABLE ranking_policy_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ranking_policy_versions FROM anon, authenticated;
ALTER TABLE ranking_snapshots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ranking_snapshots FROM anon, authenticated;
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON audit_logs FROM anon, authenticated;
ALTER TABLE question_metadata ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON question_metadata FROM anon, authenticated;
ALTER TABLE vocabulary_metadata ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON vocabulary_metadata FROM anon, authenticated;
ALTER TABLE learning_lessons ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON learning_lessons FROM anon, authenticated;
ALTER TABLE package_lessons ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON package_lessons FROM anon, authenticated;
ALTER TABLE source_assets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON source_assets FROM anon, authenticated;
ALTER TABLE exam_session_metadata ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_session_metadata FROM anon, authenticated;
ALTER TABLE profile_curriculum ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON profile_curriculum FROM anon, authenticated;
ALTER TABLE exam_exposure_order ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON exam_exposure_order FROM anon, authenticated;
ALTER TABLE learning_session_metadata ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON learning_session_metadata FROM anon, authenticated;
DROP POLICY IF EXISTS own_profile ON profiles;
CREATE POLICY own_profile ON profiles FOR SELECT TO authenticated USING (id=auth.uid() AND role='employee');
GRANT SELECT(id,employee_id,name,email,department,division,job_title,role,self_level,placement_level,baseline_hsk,baseline_work,demo,created_at) ON profiles TO authenticated;
CREATE OR REPLACE FUNCTION public.is_shared_leader() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='leader'); $$;
REVOKE ALL ON FUNCTION public.is_shared_leader() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_shared_leader() TO authenticated;
CREATE OR REPLACE VIEW public.leader_employee_directory WITH (security_barrier=true) AS SELECT id,name,department,division,job_title,self_level,placement_level,baseline_hsk,baseline_work,demo,created_at FROM public.profiles WHERE role='employee' AND public.is_shared_leader();
REVOKE ALL ON public.leader_employee_directory FROM anon,authenticated;
GRANT SELECT ON public.leader_employee_directory TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON exam_sessions;
CREATE POLICY own_or_leader_read ON exam_sessions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON exam_sessions TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON exam_results;
CREATE POLICY own_or_leader_read ON exam_results FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON exam_results TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON learning_sessions;
CREATE POLICY own_or_leader_read ON learning_sessions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON learning_sessions TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON learning_progress;
CREATE POLICY own_or_leader_read ON learning_progress FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON learning_progress TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON weekly_targets;
CREATE POLICY own_or_leader_read ON weekly_targets FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON weekly_targets TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON notifications;
CREATE POLICY own_or_leader_read ON notifications FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON notifications TO authenticated;
DROP POLICY IF EXISTS own_or_leader_read ON notification_preferences;
CREATE POLICY own_or_leader_read ON notification_preferences FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_shared_leader());
GRANT SELECT ON notification_preferences TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON departments;
CREATE POLICY authenticated_read ON departments FOR SELECT TO authenticated USING (true);
GRANT SELECT ON departments TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON divisions;
CREATE POLICY authenticated_read ON divisions FOR SELECT TO authenticated USING (true);
GRANT SELECT ON divisions TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON job_titles;
CREATE POLICY authenticated_read ON job_titles FOR SELECT TO authenticated USING (true);
GRANT SELECT ON job_titles TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON hsk_levels;
CREATE POLICY authenticated_read ON hsk_levels FOR SELECT TO authenticated USING (true);
GRANT SELECT ON hsk_levels TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON learning_packages;
CREATE POLICY authenticated_read ON learning_packages FOR SELECT TO authenticated USING (true);
GRANT SELECT ON learning_packages TO authenticated;
DROP POLICY IF EXISTS authenticated_read ON ranking_policy_versions;
CREATE POLICY authenticated_read ON ranking_policy_versions FOR SELECT TO authenticated USING (true);
GRANT SELECT ON ranking_policy_versions TO authenticated;
DROP POLICY IF EXISTS published_vocabulary ON vocabulary;
CREATE POLICY published_vocabulary ON vocabulary FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM content_versions cv WHERE cv.id=version_id AND cv.status='published' AND cv.demo=0));
DROP POLICY IF EXISTS published_versions ON content_versions;
CREATE POLICY published_versions ON content_versions FOR SELECT TO authenticated USING(status='published' AND demo=0);
GRANT SELECT ON vocabulary,content_versions TO authenticated;
DROP POLICY IF EXISTS published_package_links ON package_vocabulary;
CREATE POLICY published_package_links ON package_vocabulary FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM vocabulary v WHERE v.id=vocabulary_id));
GRANT SELECT ON package_vocabulary TO authenticated;
-- profiles, questions, options, exam snapshots, answers, reset/session/rate tables have no write grants.
-- Exam snapshots contain correct answers and are NEVER readable through PostgREST.
CREATE TABLE IF NOT EXISTS vocabulary_progress (user_id UUID NOT NULL REFERENCES profiles(id), vocabulary_id UUID NOT NULL REFERENCES vocabulary(id), status TEXT NOT NULL CHECK(status IN ('known','review','unknown')), updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,vocabulary_id));
ALTER TABLE vocabulary_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON vocabulary_progress FROM anon,authenticated;
CREATE TABLE IF NOT EXISTS official_exam_state (session_id UUID PRIMARY KEY REFERENCES exam_sessions(id), paper_id TEXT NOT NULL, answers_json TEXT NOT NULL, grading_status TEXT NOT NULL, scores_json TEXT, grading_started BIGINT);
ALTER TABLE official_exam_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON official_exam_state FROM anon,authenticated;
-- Learning Center Phase 1: backend-only; no Data API grants.

CREATE TABLE IF NOT EXISTS lc_review_state(user_id UUID NOT NULL REFERENCES profiles(id),vocabulary_id UUID NOT NULL REFERENCES vocabulary(id),due_at BIGINT NOT NULL,interval_seconds INTEGER NOT NULL,repetitions INTEGER NOT NULL DEFAULT 0,recall_successes INTEGER NOT NULL DEFAULT 0,last_correct INTEGER NOT NULL DEFAULT 0,reviewed_at BIGINT NOT NULL,PRIMARY KEY(user_id,vocabulary_id));
CREATE TABLE IF NOT EXISTS lc_reviews(id TEXT PRIMARY KEY,user_id UUID NOT NULL REFERENCES profiles(id),vocabulary_id UUID NOT NULL REFERENCES vocabulary(id),status TEXT NOT NULL,correct INTEGER,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS lc_challenges(id TEXT PRIMARY KEY,user_id UUID NOT NULL REFERENCES profiles(id),kind TEXT NOT NULL,target_id TEXT NOT NULL,payload TEXT NOT NULL,answers TEXT NOT NULL,created_at BIGINT NOT NULL,revealed_at BIGINT,submitted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS lc_xp(user_id UUID NOT NULL REFERENCES profiles(id),day TEXT NOT NULL,activity TEXT NOT NULL,target_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0 AND amount<=15),created_at BIGINT NOT NULL,PRIMARY KEY(user_id,day,activity,target_id));
CREATE TABLE IF NOT EXISTS lc_practice(id TEXT PRIMARY KEY,user_id UUID NOT NULL REFERENCES profiles(id),target_id TEXT NOT NULL,score INTEGER NOT NULL,passed INTEGER NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS lc_due_user ON lc_review_state(user_id,due_at);
CREATE INDEX IF NOT EXISTS lc_reviews_user ON lc_reviews(user_id,created_at);
CREATE INDEX IF NOT EXISTS lc_challenge_user ON lc_challenges(user_id,created_at);
CREATE INDEX IF NOT EXISTS lc_practice_user ON lc_practice(user_id,created_at);
ALTER TABLE lc_review_state ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_review_state FROM anon,authenticated;
ALTER TABLE lc_reviews ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_reviews FROM anon,authenticated;
ALTER TABLE lc_challenges ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_challenges FROM anon,authenticated;
ALTER TABLE lc_xp ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_xp FROM anon,authenticated;
ALTER TABLE lc_practice ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_practice FROM anon,authenticated;
-- Learning Center Phase 2

CREATE TABLE IF NOT EXISTS lc_activity_results(id TEXT PRIMARY KEY,user_id UUID NOT NULL REFERENCES profiles(id),kind TEXT NOT NULL,target_id TEXT NOT NULL,score INTEGER NOT NULL CHECK(score>=0 AND score<=100),completed INTEGER NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS lc_saved_words(user_id UUID NOT NULL REFERENCES profiles(id),vocabulary_id UUID NOT NULL REFERENCES vocabulary(id),created_at BIGINT NOT NULL,PRIMARY KEY(user_id,vocabulary_id));
CREATE TABLE IF NOT EXISTS lc_preferences(user_id UUID PRIMARY KEY REFERENCES profiles(id),work_days TEXT NOT NULL,rest_dates TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lc_badges(user_id UUID NOT NULL REFERENCES profiles(id),code TEXT NOT NULL,earned_at BIGINT NOT NULL,PRIMARY KEY(user_id,code));
CREATE INDEX IF NOT EXISTS lc_activity_user ON lc_activity_results(user_id,created_at);
ALTER TABLE lc_activity_results ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_activity_results FROM anon,authenticated;
ALTER TABLE lc_saved_words ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_saved_words FROM anon,authenticated;
ALTER TABLE lc_preferences ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_preferences FROM anon,authenticated;
ALTER TABLE lc_badges ENABLE ROW LEVEL SECURITY; REVOKE ALL ON lc_badges FROM anon,authenticated;
CREATE TABLE IF NOT EXISTS hsk_attempt_options(session_id UUID PRIMARY KEY REFERENCES exam_sessions(id),purpose TEXT NOT NULL CHECK(purpose IN ('promotion','simulation','learning','section','mistakes')),section TEXT CHECK(section IS NULL OR section IN ('listening','reading','writing')),policy_json TEXT NOT NULL);
ALTER TABLE hsk_attempt_options ENABLE ROW LEVEL SECURITY; REVOKE ALL ON hsk_attempt_options FROM anon,authenticated;
COMMIT;
